// Pure string parsers for filmot.com search / sidebyside pages. No DOM — works
// in Node (the "Manage" CLI) and is unit-testable against saved HTML fixtures.
//
// A search/sidebyside page contains:
//   - result cards:  <div id="vcard_<videoId>" ...> with a vlink (per-video
//     transcript URL), title, view/like/date badges, and a sidebyside link whose
//     label reveals whether the caption track is auto-generated.
//   - a transcript:  <div id="subtitlesIn"> ... <div id="sN"><a href="javascript:
//     jtt(N,ts)">▶</a>TEXT</div> ... for one video (the current result).

const ENTITIES = {
  "&nbsp;": " ",
  "&amp;": "&",
  "&lt;": "<",
  "&gt;": ">",
  "&quot;": '"',
  "&#39;": "'",
};

function decodeEntities(s) {
  return String(s || "")
    .replace(/&(nbsp|amp|lt|gt|quot|#39);/g, (m) => ENTITIES[m] || m)
    // Numeric character references (e.g. &#9654; = ▶, &#x25B6; = ▶). Live filmot
    // encodes the play glyph this way, so it must be decoded or it leaks into the
    // transcript text and breaks phrases that span a line boundary.
    .replace(/&#(\d+);/g, (_, d) => codePointOr(parseInt(d, 10)))
    .replace(/&#x([0-9a-fA-F]+);/g, (_, h) => codePointOr(parseInt(h, 16)));
}

// String.fromCodePoint for a valid code point; leave the original text otherwise.
function codePointOr(n) {
  return Number.isFinite(n) && n >= 0 && n <= 0x10ffff ? String.fromCodePoint(n) : "";
}

// filmot links are relative on the live site ("/search/…") but absolute in some
// saved pages. Normalize to an absolute URL so it's directly fetchable/navigable.
function absoluteFilmotUrl(href) {
  const h = String(href || "").trim();
  if (!h) return "";
  if (/^https?:\/\//i.test(h)) return h;
  if (h.startsWith("//")) return "https:" + h;
  if (h.startsWith("/")) return "https://filmot.com" + h;
  return h;
}

// Strip HTML tags, the ▶ play glyph and entities, collapse whitespace.
function cleanInlineText(html) {
  return decodeEntities(String(html || "").replace(/<[^>]*>/g, ""))
    .replace(/▶/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

// Parse the result cards from a search/sidebyside page.
// Returns [{ videoId, title, transcriptUrl, isAutoGenerated, views, likes, date }].
export function parseSearchResults(html) {
  const src = String(html || "");
  const cards = [];
  // Split on the vcard marker; each chunk (after the first) is one card's markup
  // up to the next vcard.
  const parts = src.split(/id="vcard_/);
  for (let i = 1; i < parts.length; i++) {
    const chunk = parts[i];
    const idM = chunk.match(/^([A-Za-z0-9_-]{6,})"/);
    if (!idM) continue;
    const videoId = idM[1];

    const vlinkM = chunk.match(/id="vlink\d+"[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/);
    const transcriptUrl = vlinkM ? absoluteFilmotUrl(decodeEntities(vlinkM[1])) : "";
    const title = vlinkM ? cleanInlineText(vlinkM[2]) : "";

    const eyeM = chunk.match(/fa-eye[^>]*><\/i>\s*([^<]+)</);
    const thumbM = chunk.match(/fa-thumbs-up[^>]*><\/i>\s*([^<]+)</);
    const dateM = chunk.match(/<span class="badge">\s*(\d{1,2} [A-Za-z]{3} \d{4})\s*<\/span>/);

    const sbsM = chunk.match(/\/sidebyside\/[^"]*/);
    const sbs = sbsM ? decodeEntities(sbsM[0]) : "";
    const isAutoGenerated = /auto-generated|\/auto\.[a-z]/i.test(sbs);

    cards.push({
      videoId,
      title,
      transcriptUrl,
      isAutoGenerated,
      views: eyeM ? eyeM[1].trim() : "",
      likes: thumbM ? thumbM[1].trim() : "",
      date: dateM ? dateM[1].trim() : "",
    });
  }
  return cards;
}

// Parse the transcript (#subtitlesIn) into ordered lines.
// Returns { videoId, videoTitle, lines: [{ idx, ts, text }] }.
export function parseTranscript(html) {
  const src = String(html || "");
  const lines = [];
  const re = /<div\b[^>]*\bid="s(\d+)"[^>]*>([\s\S]*?)<\/div>/g;
  let m;
  while ((m = re.exec(src)) !== null) {
    const idx = parseInt(m[1], 10);
    const inner = m[2];
    const tsM = inner.match(/jtt\(\d+,\s*([\d.]+)\)/);
    const ts = tsM ? parseFloat(tsM[1]) : 0;
    lines.push({ idx, ts, text: cleanInlineText(inner) });
  }

  let videoId = "";
  const vidM =
    src.match(/currentVideoID\s*=\s*['"]([A-Za-z0-9_-]{6,})/) ||
    src.match(/\/sidebyside\/([A-Za-z0-9_-]{6,})/);
  if (vidM) videoId = vidM[1];

  let videoTitle = "";
  const tM = src.match(/<title>([\s\S]*?)<\/title>/);
  if (tM) videoTitle = cleanInlineText(tM[1]).replace(/^["']+|["']+$/g, "");

  return { videoId, videoTitle, lines };
}

function joinWithOffsets(lines) {
  let joined = "";
  const spans = [];
  lines.forEach((l, i) => {
    const start = joined.length;
    joined += l.text || "";
    spans.push({ i, start, end: joined.length });
    joined += " "; // separator between lines
  });
  return { joined, spans };
}

function lineAtOffset(spans, off) {
  for (const s of spans) if (off >= s.start && off < s.end) return s.i;
  // Offset landed in the separator gap — attribute to the preceding line.
  for (let k = spans.length - 1; k >= 0; k--) if (off >= spans[k].start) return spans[k].i;
  return 0;
}

// Locate `regex` in the transcript, tolerating a match that spans adjacent lines,
// and return the match plus `before`/`after` lines of context.
// Returns { matchIndex, idx, tsStart, tsEnd, matchReason, contextLines } or null.
export function findMatchWithContext(lines, regex, before = 3, after = 3) {
  if (!Array.isArray(lines) || !lines.length || !regex) return null;
  const { joined, spans } = joinWithOffsets(lines);
  try {
    regex.lastIndex = 0;
  } catch (e) {
    /* non-global regex: ignore */
  }
  const m = regex.exec(joined);
  if (!m) return null;
  const s = m.index;
  const e = m.index + (m[0] ? m[0].length : 0);
  const lineStart = lineAtOffset(spans, s);
  const lineEnd = lineAtOffset(spans, Math.max(s, e - 1));
  const from = Math.max(0, lineStart - before);
  const to = Math.min(lines.length - 1, lineEnd + after);
  return {
    matchIndex: lineStart,
    idx: lines[lineStart].idx,
    tsStart: lines[lineStart].ts,
    tsEnd: lineEnd + 1 < lines.length ? lines[lineEnd + 1].ts : lines[lineEnd].ts,
    matchReason: "regex",
    contextLines: lines.slice(from, to + 1),
  };
}
